using WAID.Application.Services;
using WAID.Infrastructure.Persistence;
namespace WAID.Infrastructure.Tests;
public sealed class AlertPersistenceTests
{
 [Fact]public async Task Alert_state_settings_and_restart_deduplication_round_trip(){var path=Path.Combine(Path.GetTempPath(),$"waid-alert-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqliteAlertRepository(db);var settings=AlertSettings.Default with{Cooldown=TimeSpan.FromHours(8),PolicySource="OrganizationPolicy"};await repo.SaveSettingsAsync(settings,CancellationToken.None);var now=DateTimeOffset.UtcNow;var alert=new AlertNotification(Guid.NewGuid(),"storage:low","storage-low","1.0",AlertCategory.Storage,AlertSeverity.Warning,"Storage low","Free space is low.","Review storage","waid://storage",now,now,now,2,0,AlertState.Snoozed,null,now.AddHours(2),[new("storage","sample:1",now,new Dictionary<string,string>{{"freePercent","8"}})]);await repo.SaveAsync(alert,CancellationToken.None);var delivery=new AlertDelivery(Guid.NewGuid(),alert.Id,"in-app",now,AlertDeliveryStatus.Delivered,"Delivered.");await repo.SaveDeliveryAsync(delivery,CancellationToken.None);var restarted=new SqliteAlertRepository(db);var loadedSettings=await restarted.GetSettingsAsync(CancellationToken.None);Assert.Equal(settings.Cooldown,loadedSettings.Cooldown);Assert.Equal(settings.PolicySource,loadedSettings.PolicySource);Assert.Equal(settings.EnabledChannels.Order(),loadedSettings.EnabledChannels.Order());var loaded=await restarted.GetActiveByKeyAsync(alert.DeduplicationKey,CancellationToken.None);Assert.NotNull(loaded);Assert.Equal(alert.Id,loaded.Id);Assert.Equal(alert.State,loaded.State);Assert.Equal(alert.Evidence[0].Values,loaded.Evidence[0].Values);Assert.Equal(alert.Id,Assert.Single(await restarted.QueryAsync(new(State:AlertState.Snoozed),CancellationToken.None)).Id);}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}
}
